from flask import Flask, jsonify, Response, request
from typing import Any
from datetime import date, datetime, timedelta
from concurrent.futures import ThreadPoolExecutor, as_completed
from src.app.db_handler import PostgresDBHandler
from src.app.handlers.base_handler import BaseBankHandler
from src.app.exceptions import StonksError, FundNotFoundError, BankAPIError, DataParsingError
import logging

logger = logging.getLogger(__name__)


class AppRoutes:
    """Configuration class to define and register all application routes."""

    def __init__(self, app: Flask, db_inserter: PostgresDBHandler, handlers: dict[str, BaseBankHandler]) -> None:
        self.app: Flask = app
        self.db_inserter: PostgresDBHandler = db_inserter
        self.handlers: dict[str, BaseBankHandler] = handlers
        self._funds_cache: tuple[datetime, list[str]] | None = None
        self._cache_ttl: timedelta = timedelta(seconds=60)
        self._register_routes()

    def _register_routes(self) -> None:
        self.app.add_url_rule("/funds", view_func=self.my_funds, methods=["GET"])
        self.app.add_url_rule("/funds", view_func=self.add_fund, methods=["POST"])
        self.app.add_url_rule("/funds/<name>", view_func=self.remove_fund, methods=["DELETE"])
        self.app.add_url_rule("/experiment", view_func=self.experiment, methods=["GET"])
        self.app.add_url_rule("/update-rates", view_func=self.update_rates, methods=["GET", "POST"])
        self.app.add_url_rule("/gains", view_func=self.gains, methods=["GET"])
        self.app.add_url_rule("/daily-gains", view_func=self.daily_gains, methods=["GET"])

    def get_all_funds(self) -> list[str]:
        """Fetch all tracked funds from database with in-memory caching."""
        if self._funds_cache is not None:
            cached_at, cached_funds = self._funds_cache
            if datetime.now() - cached_at < self._cache_ttl:
                return cached_funds
        connection = self.db_inserter.create_connection()
        try:
            query = "SELECT entry FROM funds;"
            with connection.cursor() as cur:
                cur.execute(query)
                res = [fund[0] for fund in cur.fetchall()]
            self._funds_cache = (datetime.now(), res)
            return res
        finally:
            self.db_inserter.close_connection(connection)

    def my_funds(self) -> tuple[Response, int]:
        """Get list of all tracked funds."""
        try:
            funds = self.get_all_funds()
            return jsonify({"status": "success", "data": {"funds": funds}}), 200
        except StonksError as s_err:
            logger.error(f"Domain error fetching funds: {s_err}")
            return jsonify({'status': 'error', 'error': str(s_err)}), 400
        except Exception as err:
            logger.error(f"Unexpected error fetching funds: {err}")
            return jsonify({'status': 'error', 'error': f'Unexpected error: {err}'}), 500

    def add_fund(self) -> tuple[Response, int]:
        """Add a new fund to the tracked funds list."""
        try:
            data = request.get_json(silent=True)
            if not data or not isinstance(data.get("name"), str):
                return jsonify({"status": "error", "error": "Missing or invalid 'name' field"}), 400
            name = data["name"].strip()
            if not name:
                return jsonify({"status": "error", "error": "Fund name must not be empty"}), 400
            inserted = self.db_inserter.add_fund(name)
            if not inserted:
                return jsonify({"status": "error", "error": f"Fund '{name}' already exists"}), 409
            self._funds_cache = None
            return jsonify({"status": "success", "message": f"Fund '{name}' added"}), 201
        except StonksError as s_err:
            logger.error(f"Domain error adding fund: {s_err}")
            return jsonify({'status': 'error', 'error': str(s_err)}), 500
        except Exception as err:
            logger.error(f"Unexpected error adding fund: {err}")
            return jsonify({'status': 'error', 'error': f'Unexpected error: {err}'}), 500

    def remove_fund(self, name: str) -> tuple[Response, int]:
        """Remove a fund from the tracked funds list."""
        try:
            deleted = self.db_inserter.remove_fund(name)
            if not deleted:
                return jsonify({"status": "error", "error": f"Fund '{name}' not found"}), 404
            self._funds_cache = None
            return jsonify({"status": "success", "message": f"Fund '{name}' removed"}), 200
        except StonksError as s_err:
            logger.error(f"Domain error removing fund: {s_err}")
            return jsonify({'status': 'error', 'error': str(s_err)}), 500
        except Exception as err:
            logger.error(f"Unexpected error removing fund: {err}")
            return jsonify({'status': 'error', 'error': f'Unexpected error: {err}'}), 500

    def experiment(self) -> str:
        """Experimental endpoint."""
        return "tbd"

    def _do_update_rates(self) -> tuple[Response, int]:
        """Core logic to update fund data from all bank APIs."""
        try:
            funds = self.get_all_funds()
            updated_count = 0
            skipped = []

            with ThreadPoolExecutor(max_workers=8) as executor:
                future_to_fund = {}
                for fund in funds:
                    bank_name = fund.split(" ")[0]
                    if bank_name not in self.handlers:
                        logger.warning(f"No handler found for bank: {bank_name}")
                        skipped.append(fund)
                        continue
                    future = executor.submit(self.handlers[bank_name].get_rate, fund)
                    future_to_fund[future] = fund

                for future in as_completed(future_to_fund):
                    fund = future_to_fund[future]
                    try:
                        rate = future.result()
                        self.db_inserter.insert_value(date.today(), fund, rate.value)
                        updated_count += 1
                    except FundNotFoundError as fnf:
                        logger.warning(f"Fund not found: {fnf}")
                    except (BankAPIError, DataParsingError) as api_err:
                        logger.error(f"API error for {fund}: {api_err}")
                    except StonksError as s_err:
                        logger.error(f"General domain error for {fund}: {s_err}")
                    except Exception as ex:
                        logger.error(f"Unexpected error for {fund}: {ex}")

            # Invalidate funds cache after update
            self._funds_cache = None
            logger.info(f"Successfully updated {updated_count} funds")
            return jsonify({
                "status": "success",
                "message": f"Data updated successfully for {updated_count} funds",
                "date": str(date.today())
            }), 200

        except StonksError as s_err:
            logger.error(f"Domain error in data update: {s_err}")
            return jsonify({'error': str(s_err)}), 500
        except Exception as err:
            logger.error(f"Unexpected error in data update: {err}")
            return jsonify({'error': f'Unexpected error: {err}'}), 500

    def update_rates(self) -> tuple[Response, int]:
        """Update fund data from all bank APIs using parallel fetching."""
        return self._do_update_rates()

    def gains(self) -> tuple[Response, int]:
        """Get cumulative investment gains by date."""
        try:
            result = self.db_inserter.read_gains()
            return jsonify({"status": "success", "data": {"gains": result}}), 200
        except Exception as err:
            logger.error(f"Error reading gains: {err}")
            return jsonify({'status': 'error', 'error': f'Error reading gains: {err}'}), 500

    def daily_gains(self) -> tuple[Response, int]:
        """Get daily investment gains by date."""
        try:
            result = self.db_inserter.read_daily_gain()
            return jsonify({"status": "success", "data": {"daily_gains": result}}), 200
        except Exception as err:
            logger.error(f"Error reading daily gains: {err}")
            return jsonify({'status': 'error', 'error': f'Error reading daily gains: {err}'}), 500

from decimal import Decimal


class RateForDate:
    def __init__(self, date: str, value: Decimal) -> None:
        self.date = date
        self.value = value

    def __str__(self) -> str:
        return f"{self.value} as of {self.date}"

class StonksError(Exception):
    """Base exception for all errors in the stonks application."""
    pass

class BankAPIError(StonksError):
    """Raised when an error occurs during a request to a bank API."""
    pass

class FundNotFoundError(StonksError):
    """Raised when a requested fund cannot be found in the bank's data or mapping."""
    pass

class DataParsingError(StonksError):
    """Raised when the response from a bank API cannot be parsed correctly."""
    pass
